function Failure-Of($ErrorRecord){$e=$ErrorRecord.Exception;while($e.InnerException){$e=$e.InnerException};$r=[ordered]@{ok=$false;exception=$e.GetType().FullName;message=$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.EncoderFallbackException]){$r.unknown=[int]$e.CharUnknown;$r.index=$e.Index;$r.high=[int]$e.CharUnknownHigh;$r.low=[int]$e.CharUnknownLow;$r.isPair=$e.IsUnknownSurrogate()};if($e -is [Text.DecoderFallbackException]){$r.bytesUnknown=[int[]]$e.BytesUnknown;$r.index=$e.Index};return $r}


$replacements=@(@(),@(63),@(65,66),@(55296,56320));$profiles=[Collections.Generic.List[object]]::new();$calls=0
function Capture-Write($Codec,[bool]$Encode,[int[]]$Source,[bool]$Stateful,[bool]$Flush){if($null -eq $Source){$Source=[int[]]@()};$destination=if($Encode){,[byte[]](@(99)*35)}else{,[char[]](@(99)*35)};try{$value=if($Encode){if($Stateful){$Codec.GetBytes([char[]][int[]]$Source,0,$Source.Count,$destination,1,$Flush)}else{$Codec.GetBytes([char[]][int[]]$Source,0,$Source.Count,$destination,1)}}else{if($Stateful){$Codec.GetChars([byte[]][int[]]$Source,0,$Source.Count,$destination,1,$Flush)}else{$Codec.GetChars([byte[]][int[]]$Source,0,$Source.Count,$destination,1)}};$result=[ordered]@{ok=$true;count=$value}}catch{$result=Failure-Of $_};return [ordered]@{result=$result;after=[int[]]$destination}}

foreach($kind in @('UTF8','UTF16LE','UTF16BE')){foreach($old in $replacements){foreach($next in $replacements){$rows=@()
 foreach($seedMode in 0..2){foreach($precreate in @($false,$true)){foreach($sameProvider in @($false,$true)){$prototype=switch($kind){'UTF8'{[Text.UTF8Encoding]::new($false,$false)};'UTF16LE'{[Text.UnicodeEncoding]::new($false,$true,$false)};'UTF16BE'{[Text.UnicodeEncoding]::new($true,$true,$false)}};$owner=[Text.Encoding]$prototype.Clone();$oldE=[Text.EncoderReplacementFallback]::new([string]::new([char[]][int[]]$old));$oldD=[Text.DecoderReplacementFallback]::new([string]::new([char[]][int[]]$old));$nextE=[Text.EncoderReplacementFallback]::new([string]::new([char[]][int[]]$next));$nextD=[Text.DecoderReplacementFallback]::new([string]::new([char[]][int[]]$next));$owner.EncoderFallback=$oldE;$owner.DecoderFallback=$oldD;$encoder=$owner.GetEncoder();$decoder=$owner.GetDecoder();if($precreate){$ignored=$encoder.FallbackBuffer;$ignored=$decoder.FallbackBuffer};$seedChars=if($seedMode -eq 0){[int[]]@()}else{[int[]]@(55296)};$seedBytes=if($seedMode -eq 0){[int[]]@()}elseif($kind -eq 'UTF8'){if($seedMode -eq 1){[int[]]@(226)}else{[int[]]@(240,144)}}elseif($seedMode -eq 1){[int[]]@(0)}elseif($kind -eq 'UTF16LE'){[int[]]@(0,216)}else{[int[]]@(216,0)};$events=[ordered]@{};$events.seedEncoder=Capture-Write $encoder $true $seedChars $true $false;$events.seedDecoder=Capture-Write $decoder $false $seedBytes $true $false;$oldBufferE=$encoder.FallbackBuffer;$oldBufferD=$decoder.FallbackBuffer;$assignedE=if($sameProvider){$oldE}else{$nextE};$assignedD=if($sameProvider){$oldD}else{$nextD};$encoder.Fallback=$assignedE;$decoder.Fallback=$assignedD;$newBufferE=$encoder.FallbackBuffer;$newBufferD=$decoder.FallbackBuffer
 $identity=[ordered]@{encoderAssigned=[object]::ReferenceEquals($encoder.Fallback,$assignedE);decoderAssigned=[object]::ReferenceEquals($decoder.Fallback,$assignedD);ownerEncoderUnchanged=[object]::ReferenceEquals($owner.EncoderFallback,$oldE);ownerDecoderUnchanged=[object]::ReferenceEquals($owner.DecoderFallback,$oldD);encoderBufferChanged=(-not[object]::ReferenceEquals($oldBufferE,$newBufferE));decoderBufferChanged=(-not[object]::ReferenceEquals($oldBufferD,$newBufferD));newEncoderRemaining=$newBufferE.Remaining;newDecoderRemaining=$newBufferD.Remaining}
 $oldBufferProbes=@();foreach($buffer in @($oldBufferE,$oldBufferD)){$oldBufferProbes+=@([ordered]@{remainingBefore=$buffer.Remaining;next=[int]$buffer.GetNextChar();remainingAfterNext=$buffer.Remaining;previous=$buffer.MovePrevious();remainingAfterPrevious=$buffer.Remaining})}
 $events.flushExistingEncoder=Capture-Write $encoder $true ([int[]]@()) $true $true;$events.flushExistingDecoder=Capture-Write $decoder $false ([int[]]@()) $true $true;$events.reuseExistingEncoder=Capture-Write $encoder $true ([int[]]@(56320)) $true $true;$events.reuseExistingDecoder=Capture-Write $decoder $false ([int[]]@(255)) $true $true;$events.ownerEncoder=Capture-Write $owner $true ([int[]]@(56320)) $false $true;$events.ownerDecoder=Capture-Write $owner $false ([int[]]@(255)) $false $true;$calls+=$events.Count
 $rows+=@([ordered]@{seedMode=$seedMode;precreate=$precreate;sameProvider=$sameProvider;seedChars=[int[]]@($seedChars|Where-Object {$null -ne $_});seedBytes=[int[]]@($seedBytes|Where-Object {$null -ne $_});identity=$identity;oldBufferProbes=$oldBufferProbes;events=$events})
 }}};$profiles.Add([ordered]@{kind=$kind;oldReplacement=[int[]]$old;nextReplacement=[int[]]$next;rows=$rows})
}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();nativeCalls=$calls;profiles=$profiles.ToArray();qualification='NATIVE_SELECTED_STATEFUL_FALLBACK_REPLACEMENT_PENDING_CARRY_AND_BUFFER_IDENTITY_ONLY; NONEMPTY_BUFFER_CALLBACKS_FULL_PARITY_AND_TASK_ACCEPTANCE_OPEN'};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 15 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS direct stateful fallback replacement: $calls native calls"
